+/// The reason recorded by [`mark_current_stale`], when the current snapshot is
+/// marked stale. `None` when it is current or no reason was recorded.
+pub fn stale_reason(root: &Path) -> Result<Option<String>, ForgeError> {
+    Ok(read_manifest(root)?
+        .filter(|m| m.stale)
+        .and_then(|m| m.stale_reason))
+}
+
 /// Whether the current snapshot is marked stale.
 pub fn is_stale(root: &Path) -> Result<bool, ForgeError> {
     Ok(read_manifest(root)?.map(|m| m.stale).unwrap_or(false))
